// pt_metal_host.mm: Objective-C++ Metal host. Owns the device, the buffers and
// the compute pipelines, and performs one frame per render_frame call. No
// render pipelines and no Metal ray-tracing APIs are used anywhere.
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

#include "pt_metal_host.hpp"

#include <algorithm>
#include <cstdio>
#include <cstring>

namespace pt {

struct MetalPathTracer::Impl {
    id<MTLDevice> device = nil;
    id<MTLCommandQueue> queue = nil;
    id<MTLComputePipelineState> trace_pipeline = nil;
    id<MTLComputePipelineState> trace_samples_pipeline = nil;
    id<MTLComputePipelineState> combine_pipeline = nil;

    id<MTLBuffer> node_buffer = nil;         // 16-byte quantized BVH nodes
    id<MTLBuffer> triangle_buffer = nil;     // packed origin/edge1/edge2
    id<MTLBuffer> normal_buffer = nil;       // per-triangle vertex normals
    id<MTLBuffer> params_buffer = nil;
    id<MTLBuffer> radiance_buffer = nil;     // float4 per pixel (linear estimate)
    id<MTLBuffer> image_buffer = nil;        // uchar4 per pixel (tone mapped)
    id<MTLBuffer> counter_buffer = nil;      // uint camera-sample counter
    id<MTLBuffer> sample_buffer = nil;       // float4 per camera sample

    int width = 0;
    int height = 0;
    bool sample_parallel = false;   // false = classic one-thread-per-pixel kernel

    bool fail(NSString* message, std::string& error) const {
        error = message.length > 0 ? std::string([message UTF8String]) : std::string("metal error");
        return false;
    }
};

namespace {

// Reads a text file into an NSString, returning nil on failure.
NSString* read_text(NSString* path) {
    NSData* data = [NSData dataWithContentsOfFile:path];
    if (data == nil) {
        return nil;
    }
    return [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
}

}  // namespace

MetalPathTracer::MetalPathTracer() : impl_(new Impl()) {}

MetalPathTracer::~MetalPathTracer() {
    delete impl_;
}

bool MetalPathTracer::init(const std::string& shader_dir, const std::string& shared_header_path,
                           std::string& error) {
    impl_->device = MTLCreateSystemDefaultDevice();
    if (impl_->device == nil) {
        return impl_->fail(@"no Metal device available", error);
    }
    impl_->queue = [impl_->device newCommandQueue];

    NSString* dir = [NSString stringWithUTF8String:shader_dir.c_str()];
    NSString* header = read_text([NSString stringWithUTF8String:shared_header_path.c_str()]);
    if (header == nil) {
        return impl_->fail(@"cannot read shared shader header", error);
    }

    NSMutableString* source = [NSMutableString string];
    [source appendString:@"#include <metal_stdlib>\nusing namespace metal;\n"];
    // The shared struct header is prepended so both sides agree on the layout;
    // its include guard is meaningless inside a single translation unit.
    [source appendString:[header stringByReplacingOccurrencesOfString:@"#pragma once"
                                                           withString:@""]];

    // The kernel files have dependencies (pt_trace.metal defines the helpers
    // used by the tone mapping helper, which the integrator calls), so they are
    // concatenated in this fixed order; any other .metal files are appended
    // afterwards alphabetically.
    NSArray<NSString*>* ordered =
        @[ @"pt_trace.metal", @"pt_tonemap.metal", @"pt_integrator.metal" ];
    NSFileManager* fm = [NSFileManager defaultManager];
    NSArray<NSString*>* names = [[fm contentsOfDirectoryAtPath:dir error:nil]
        sortedArrayUsingSelector:@selector(compare:)];
    NSMutableArray<NSString*>* ordered_names = [NSMutableArray array];
    for (NSString* name in ordered) {
        if ([names containsObject:name]) {
            [ordered_names addObject:name];
        }
    }
    for (NSString* name in names) {
        if (![name hasSuffix:@".metal"]) {
            continue;
        }
        if (![ordered containsObject:name]) {
            [ordered_names addObject:name];
        }
    }

    bool saw_kernel = false;
    for (NSString* name in ordered_names) {
        NSString* text = read_text([dir stringByAppendingPathComponent:name]);
        if (text == nil) {
            return impl_->fail(@"cannot read shader file", error);
        }
        [source appendString:@"\n"];
        [source appendString:text];
        saw_kernel = true;
    }
    if (!saw_kernel) {
        return impl_->fail(@"no .metal files found next to the binary", error);
    }

    NSError* ns_error = nil;
    MTLCompileOptions* options = [[MTLCompileOptions alloc] init];
    // Fast math lets the compiler use hardware reciprocal/sqrt approximations
    // and fused multiply-add in the traversal and BSDF math. The estimator is
    // unchanged (identical sample streams), only float rounding moves.
    options.fastMathEnabled = YES;
    id<MTLLibrary> library = [impl_->device newLibraryWithSource:source options:options
                                                           error:&ns_error];
    if (library == nil) {
        NSString* combined = [NSString stringWithFormat:@"shader compile failed: %@",
                              ns_error.localizedDescription];
        NSLog(@"%@", combined);
        return impl_->fail(combined, error);
    }

    impl_->trace_pipeline = [impl_->device
        newComputePipelineStateWithFunction:[library newFunctionWithName:@"trace_kernel"]
                                      error:&ns_error];
    if (impl_->trace_pipeline == nil) {
        return impl_->fail(@"trace_kernel pipeline failed", error);
    }

    // Sample-parallel pair: trace one camera sample per thread, then combine in
    // exact sample order. Both are built unconditionally; the classic kernel is
    // still used when the per-sample buffer would be too large.
    impl_->trace_samples_pipeline = [impl_->device
        newComputePipelineStateWithFunction:[library newFunctionWithName:@"trace_samples_kernel"]
                                      error:&ns_error];
    if (impl_->trace_samples_pipeline == nil) {
        return impl_->fail(@"trace_samples_kernel pipeline failed", error);
    }
    impl_->combine_pipeline = [impl_->device
        newComputePipelineStateWithFunction:[library newFunctionWithName:@"combine_kernel"]
                                      error:&ns_error];
    if (impl_->combine_pipeline == nil) {
        return impl_->fail(@"combine_kernel pipeline failed", error);
    }

    impl_->params_buffer = [impl_->device newBufferWithLength:sizeof(PtParams)
                                                      options:MTLResourceStorageModeShared];
    impl_->counter_buffer = [impl_->device newBufferWithLength:sizeof(uint32_t)
                                                      options:MTLResourceStorageModeShared];
    return true;
}

bool MetalPathTracer::upload_mesh(const GpuMeshData& mesh, std::string& error) {
    impl_->node_buffer = [impl_->device newBufferWithBytes:mesh.nodes
                                                   length:mesh.node_count * sizeof(PtBvhNodeQ)
                                                  options:MTLResourceStorageModeShared];
    impl_->triangle_buffer = [impl_->device newBufferWithBytes:mesh.triangles
                                                       length:mesh.triangle_count * sizeof(PtTri)
                                                      options:MTLResourceStorageModeShared];
    impl_->normal_buffer = [impl_->device newBufferWithBytes:mesh.normals
                                                     length:mesh.normal_count * sizeof(PtTriNormals)
                                                    options:MTLResourceStorageModeShared];
    if (impl_->node_buffer == nil || impl_->triangle_buffer == nil ||
        impl_->normal_buffer == nil) {
        return impl_->fail(@"mesh upload failed", error);
    }
    return true;
}

bool MetalPathTracer::allocate(int width, int height, int spp, std::string& error) {
    const NSUInteger pixels = static_cast<NSUInteger>(width) * static_cast<NSUInteger>(height);
    impl_->width = width;
    impl_->height = height;
    impl_->radiance_buffer = [impl_->device newBufferWithLength:pixels * sizeof(float) * 4
                                                       options:MTLResourceStorageModeShared];
    impl_->image_buffer = [impl_->device newBufferWithLength:pixels * 4
                                                    options:MTLResourceStorageModeShared];
    if (impl_->radiance_buffer == nil || impl_->image_buffer == nil) {
        return impl_->fail(@"image allocation failed", error);
    }

    // One float4 per camera sample for the sample-parallel layout. Allocated
    // here, outside the timed region, and only up to a fixed cap so a huge
    // resolution * spp cannot exhaust memory; above the cap the classic kernel
    // is used instead (same image, same RNG streams).
    const NSUInteger sample_bytes = pixels * static_cast<NSUInteger>(spp) * sizeof(float) * 3;
    const NSUInteger kSampleCap = static_cast<NSUInteger>(1.5e9);
    if (getenv("PT_CLASSIC") == nil && sample_bytes <= kSampleCap) {
        impl_->sample_buffer =
            [impl_->device newBufferWithLength:sample_bytes
                                       options:MTLResourceStorageModeShared];
        impl_->sample_parallel = (impl_->sample_buffer != nil);
    } else {
        impl_->sample_buffer = nil;
        impl_->sample_parallel = false;
    }
    return true;
}

bool MetalPathTracer::render_frame(const PtParams& params, std::vector<float>& radiance,
                                   std::vector<unsigned char>& rgba8, unsigned int& sample_count,
                                   double& gpu_ms, std::string& error) {
    std::memcpy([impl_->params_buffer contents], &params, sizeof(PtParams));
    std::memset([impl_->counter_buffer contents], 0, sizeof(uint32_t));

    const NSUInteger width = params.width;
    const NSUInteger height = params.height;

    // Tuning knob for the threadgroup shape; the output is independent of it
    // because every pixel is computed by exactly one thread. 32x4 measured
    // fastest with the 32-wide Morton tile (one group spans exactly one tile
    // row); 16x8 was the best before the tile widened.
    NSUInteger group_w = 32;
    NSUInteger group_h = 4;
    const char* shape = getenv("PT_TG");
    if (shape != nil) {
        sscanf(shape, "%lux%lu", &group_w, &group_h);
    }
    if (group_w == 0 || group_h == 0 || group_w * group_h > 1024) {
        group_w = 32;
        group_h = 4;
    }
    const NSUInteger trace_limit = [impl_->trace_pipeline maxTotalThreadsPerThreadgroup];
    const NSUInteger trace_total = std::min<NSUInteger>(group_w * group_h, trace_limit);
    const NSUInteger trace_rows = std::max<NSUInteger>(1, trace_total / group_w);

    id<MTLCommandBuffer> command_buffer = [impl_->queue commandBuffer];

    // The grid is rounded up to whole 32-wide Morton tiles; threads outside the
    // image return before touching any buffer.
    const NSUInteger grid_w = ((width + 31) / 32) * 32;
    const NSUInteger grid_h = ((height + 31) / 32) * 32;

    if (impl_->sample_parallel) {
        // Dispatch 1: one thread per camera sample (grid z = spp), writing the
        // per-sample radiance sample-major. Dispatch 2: one thread per pixel
        // combining the samples in increasing order, tone mapping and counting.
        // Both dispatches are inside the same command buffer, so the timed
        // region and the reported gpu_ms cover exactly the same work as before.
        id<MTLComputeCommandEncoder> trace_encoder = [command_buffer computeCommandEncoder];
        [trace_encoder setComputePipelineState:impl_->trace_samples_pipeline];
        [trace_encoder setBuffer:impl_->params_buffer offset:0 atIndex:0];
        [trace_encoder setBuffer:impl_->node_buffer offset:0 atIndex:1];
        [trace_encoder setBuffer:impl_->triangle_buffer offset:0 atIndex:2];
        [trace_encoder setBuffer:impl_->normal_buffer offset:0 atIndex:3];
        [trace_encoder setBuffer:impl_->sample_buffer offset:0 atIndex:7];
        [trace_encoder dispatchThreads:MTLSizeMake(grid_w, grid_h, params.spp)
                 threadsPerThreadgroup:MTLSizeMake(group_w, trace_rows, 1)];
        [trace_encoder endEncoding];

        id<MTLComputeCommandEncoder> combine_encoder = [command_buffer computeCommandEncoder];
        [combine_encoder setComputePipelineState:impl_->combine_pipeline];
        [combine_encoder setBuffer:impl_->params_buffer offset:0 atIndex:0];
        [combine_encoder setBuffer:impl_->sample_buffer offset:0 atIndex:7];
        [combine_encoder setBuffer:impl_->radiance_buffer offset:0 atIndex:4];
        [combine_encoder setBuffer:impl_->counter_buffer offset:0 atIndex:5];
        [combine_encoder setBuffer:impl_->image_buffer offset:0 atIndex:6];
        [combine_encoder dispatchThreads:MTLSizeMake(width, height, 1)
                   threadsPerThreadgroup:MTLSizeMake(16, 8, 1)];
        [combine_encoder endEncoding];
    } else {
        // Single compute dispatch: the kernel traces every camera sample of its
        // pixel, writes the linear estimate (which becomes the PFM) and tone
        // maps the same value into the 8-bit image, so no second pass is needed.
        id<MTLComputeCommandEncoder> trace_encoder = [command_buffer computeCommandEncoder];
        [trace_encoder setComputePipelineState:impl_->trace_pipeline];
        [trace_encoder setBuffer:impl_->params_buffer offset:0 atIndex:0];
        [trace_encoder setBuffer:impl_->node_buffer offset:0 atIndex:1];
        [trace_encoder setBuffer:impl_->triangle_buffer offset:0 atIndex:2];
        [trace_encoder setBuffer:impl_->normal_buffer offset:0 atIndex:3];
        [trace_encoder setBuffer:impl_->radiance_buffer offset:0 atIndex:4];
        [trace_encoder setBuffer:impl_->counter_buffer offset:0 atIndex:5];
        [trace_encoder setBuffer:impl_->image_buffer offset:0 atIndex:6];
        [trace_encoder dispatchThreads:MTLSizeMake(grid_w, grid_h, 1)
                 threadsPerThreadgroup:MTLSizeMake(group_w, trace_rows, 1)];
        [trace_encoder endEncoding];
    }
    if (getenv("PT_DEBUG") != nil) {
        NSLog(@"[pt] max_threads_per_group trace=%lu sample_parallel=%d",
              (unsigned long)[impl_->trace_pipeline maxTotalThreadsPerThreadgroup],
              (int)impl_->sample_parallel);
    }

    [command_buffer commit];
    [command_buffer waitUntilCompleted];

    gpu_ms = 1000.0 * command_buffer.GPUEndTime - 1000.0 * command_buffer.GPUStartTime;

    const NSUInteger pixels = width * height;
    radiance.assign(static_cast<float*>([impl_->radiance_buffer contents]),
                    static_cast<float*>([impl_->radiance_buffer contents]) + pixels * 4);
    const unsigned char* image = static_cast<const unsigned char*>([impl_->image_buffer contents]);
    rgba8.assign(image, image + pixels * 4);
    sample_count = *static_cast<uint32_t*>([impl_->counter_buffer contents]);
    return true;
}

}  // namespace pt
